import{_ as o,l as i,o as r,c as s,v as E,p as d,x as l,d as t,i as A,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"BART 与去噪编解码","description":"","frontmatter":{"title":"BART 与去噪编解码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bart-denoising.md","filePath":"llm/bart-denoising.md","lastUpdated":1789023840000}'),B={name:"llm/bart-denoising.md"};function m(h,e,c,T,u,f){const n=i("Mermaid");return r(),s("div",null,[e[1]||(e[1]=E('<h1 id="bart-与去噪编解码" tabindex="-1">BART 与去噪编解码 <a class="header-anchor" href="#bart-与去噪编解码" aria-label="Permalink to &quot;BART 与去噪编解码&quot;">​</a></h1><div class="epigraph"><p>用任意噪声函数损坏文本，再训练一个标准的编码器–解码器去重建原文；预训练于是与微调时的生成接口对齐。</p><footer>—— Lewis et al., BART: Denoising Sequence-to-Sequence Pre-training, ACL 2020</footer></div><p><a href="/llm/t5-relative-bias">上一课</a>解决了编解码注意力里位置怎么进 logits。结构仍是「源完整、目标自回归」，但还没有说明<strong>预训练目标</strong>怎样才能让这条结构在生成微调时不裂缝。<a href="/llm/masked-lm">掩码语言模型</a>挖词、只在被挖位置算损失，解码器从来没有被训练去写一整句。本课补 BART：噪声加在源侧，解码器从左到右重建干净文本。后课比较纯解码器与编解码器时，默认你会「去噪预训 = 编码器读脏源、解码器写净目标」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BERT 编码器预训练结束，生成要对每个位置迭代填掩码，或另接一个从未用去噪目标训过的解码器。T5 把所有任务收成文本进、文本出，源侧是已经写成自然语言的指令与输入，不是「被挖烂的同一句话」。缺口是：希望预训练时的计算图与摘要、翻译、改写微调时同构——编码器看见损坏的源，解码器自回归写出未损坏的目标。</p><p>损坏必须足够重，编码器才不能靠局部抄写；又必须保留可恢复的线索，否则任务退化成无条件语言模型，编码器闲置。BART 要选的是噪声族，不是再设计一种注意力。</p><p><span class="marginnote">T5 的 span 腐蚀也是去噪，但源里留下哨兵、目标只输出被挖的片段。BART 的目标是<strong>整段原文</strong>，接口更接近「给定脏文档，写干净文档」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准 Transformer 编解码：编码器双向，解码器因果自注意力加<a href="/llm/encoder-decoder-attention">编码器–解码器注意力</a>。预训练时对无监督文本施加一种或多种噪声，编码器吃噪声后的序列，解码器以教师强制重建原始 token 序列，损失是整句的负对数似然。</p><p>Lewis 等人比较的噪声包括：随机 token 删除、文本填充（把一段换成单个掩码）、句子打乱、文档旋转、token 掩码。实践里填充加句子打乱对生成任务更有效——编码器必须跨句重组，解码器必须写出完整表面形式。微调时噪声关掉，源改成下游输入（文章、问句），目标改成下游输出（摘要、答案）。</p><h3 id="与-mlm-头的差别" tabindex="-1">与 MLM 头的差别 <a class="header-anchor" href="#与-mlm-头的差别" aria-label="Permalink to &quot;与 MLM 头的差别&quot;">​</a></h3><p>MLM 只在 15% 位置上有监督信号，其余位置的隐状态不直接接到词表。BART 的解码器每一步都有下一个词损失，编码器的双向表示通过交叉注意力被每一步查询。编码器因此被训练成「给生成器当记忆」，而不是「给分类头当特征」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>噪声把源与目标的表面对齐打乱。删除与填充造成长度不匹配，交叉注意力必须学会多对一、一对多的对齐，而不能假设位置 \\(i\\) 抄源位置 \\(i\\)。句子打乱迫使编码器在双向栈里恢复篇章顺序，相对位置偏置或绝对位置都只提供局部线索，全局顺序要靠内容。</p><p>解码器的因果掩码保证生成接口：推理时左边是已写出的摘要，右边是空的，与训练时教师强制看见的前缀一致。这是 BERT 式填词做不到的对齐。</p><p><span class="marginnote">去噪强度是超参。过轻，模型抄源；过重，编码器提供的记忆接近无信息，模型退化为解码器只语言模型，白付一层交叉注意力的计算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>BART 不规定必须用 T5 相对偏置，原文用的是标准 Transformer 位置；本课把它接在相对偏置之后，是课序上的编解码工具箱，不是声称两篇论文共用同一套位置。判别任务上，BART 仍可用编码器端特征，但预训练主业是生成，<code>[CLS]</code> 不是一等公民。纯理解、短分类，双向编码器加 MLM 往往更便宜。</p>',18)),(r(),d(p,null,{default:l(()=>[A(n,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%B9%B2%E5%87%80%E6%96%87%E6%9C%AC%22%5D%20--%3E%20N%5B%22%E5%99%AA%E5%A3%B0%EF%BC%9A%E5%A1%AB%E5%85%85%20%2F%20%E6%89%93%E4%B9%B1%20%2F%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20N%20--%3E%20ENC%5B%22%E5%8F%8C%E5%90%91%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20ENC%20--%3E%20MEM%5B%22%E6%BA%90%E4%BE%A7%E8%AE%B0%E5%BF%86%22%5D%0A%20%20MEM%20--%3E%20XATT%5B%22%E7%BC%96%E7%A0%81%E5%99%A8-%E8%A7%A3%E7%A0%81%E5%99%A8%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20DEC%5B%22%E5%9B%A0%E6%9E%9C%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%20--%3E%20XATT%0A%20%20XATT%20--%3E%20Y%5B%22%E9%87%8D%E5%BB%BA%E5%8E%9F%E6%96%87%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"BART 用标准编解码器做去噪自编码：源侧任意噪声，目标侧整句重建，使预训练与生成微调同构。"),a("li",null,"相对 MLM，监督信号覆盖每一个目标位置，编码器被训成生成器用的记忆。"),a("li",null,"填充与句打乱故意破坏长度与顺序对齐，交叉注意力必须真正对齐，而不能按下标抄。"),a("li",null,"噪声过重会把模型退化成不用源的语言模型。"),a("li",null,[t("出处：Lewis et al., "),a("em",null,"BART"),t(", ACL 2020。")])],-1))])}const g=o(B,[["render",m]]);export{_ as __pageData,g as default};
